sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.features-section {
  width: 100%;
  padding: 90px 8%;
  background: #ffffff;
  font-family: Arial, sans-serif;
}

.features-heading {
  max-width: 750px;
  margin: 0 auto 55px;
  text-align: center;
}

.features-tag {
  color: #2563eb;
  font-size: 12px;
  font-weight: bold;
  letter-spacing: 1.5px;
}

.features-heading h2 {
  margin: 12px 0 15px;
  color: #111827;
  font-size: 36px;
  font-weight: 700;
}

.features-heading p {
  margin: 0;
  color: #6b7280;
  font-size: 16px;
  line-height: 1.6;
}

.features-grid {
  max-width: 1150px;
  margin: auto;

  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 25px;
}

.feature-card {
  padding: 30px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  background: #ffffff;

  transition: 0.3s;
}

.feature-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 12px 25px rgba(0,0,0,0.08);
}

.feature-icon {
  width: 58px;
  height: 58px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 20px;

  background: #eff6ff;
  color: #2563eb;

  border-radius: 12px;
  font-size: 24px;
}

.feature-card h3 {
  margin: 0 0 10px;
  color: #111827;
  font-size: 19px;
}

.feature-card p {
  margin: 0;
  color: #6b7280;
  font-size: 14px;
  line-height: 1.6;
}

@media (max-width: 900px) {
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .features-grid {
    grid-template-columns: 1fr;
  }

  .features-heading h2 {
    font-size: 30px;
  }
}
